const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

const wh = $('webhook-entry').first().json;
const body = wh.body ?? wh;
const s = body.script ?? {};
const narrationText = [s.hook, s.intro, (s.features ?? []).join('. '),
  s.useCase, s.explanation, s.cta].filter(Boolean).join(' ');
const checks = [];
if (/₹|Rs\.?\s*\d|\$\s*\d|\bprice\b|\bcost\b/i.test(narrationText))
  checks.push('price_mentioned_in_narration');
if (!narrationText || narrationText.length < 20) checks.push('narration_too_short');
return [{ json: { product: body.product ?? {}, script: s,
  visualBrief: body.visualBrief ?? [], narrationText, checks,
  clean: checks.length === 0 } }];

const j = $input.first().json;
return [{ json: { product: j.product, script: j.script, visualBrief: j.visualBrief,
  voiceBrief: { voice: 'hi-IN-SwaraNeural', narrationText: j.narrationText,
    music: False, sfx: False },
  todo: 'SYNTHESIS TODO: Edge TTS hi-IN-SwaraNeural (unreachable from some networks — see runbook)' } }];
